message.content:
这是为您生成的第1页封面 HTML 代码，主题为“长资料覆盖核验”。页面采用深绿与金色的商务风格，包含标题、副标题、唯一事实来源标注和四个章节导航，右下角清晰标注汇报日期缺失，避免编造日期。
```html
<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"/>
<style>
  html,body{margin:0;padding:0;background:#F5F2E9;}
  *{box-sizing:border-box;}
  .slide{
    position:relative;width:1920px;height:1080px;overflow:hidden;
    background:#F5F2E9;color:#1B2620;
    font-family:'PingFang SC','Hiragino Sans GB','Microsoft YaHei','Helvetica Neue',Arial,sans-serif;
  }
  :root{
    --bg:#F5F2E9; --ink:#1B2620; --muted:#5C665D;
    --olive:#4F5E43; --gold:#B4914A; --steel:#8C9FB2; --line:#A3AC9E;
  }
  .serif{font-family:'Songti SC','Noto Serif CJK SC','Source Han Serif SC',Georgia,serif;}

  /* ---------- background field ---------- */
  .bg-field{position:absolute;inset:0;z-index:0;background:
    radial-gradient(1100px 780px at 2% 0%,rgba(180,145,74,.10),transparent 70%),
    radial-gradient(900px 760px at 48% 46%,rgba(140,159,178,.11),transparent 70%),
    radial-gradient(980px 780px at 96% 96%,rgba(79,94,67,.11),transparent 72%),
    linear-gradient(168deg,#F8F5EC 0%,#F5F2E9 52%,#EFECE1 100%);}
  .bg-field:after{content:"";position:absolute;inset:0;
    background:repeating-linear-gradient(90deg,rgba(27,38,32,.042) 0 1px,transparent 1px 160px);}
  .gridline{position:absolute;z-index:2;top:0;width:1px;height:1080px;background:rgba(27,38,32,.055);}
  .gl1{left:480px;} .gl2{left:960px;} .gl3{left:1440px;}
  .soft-prism{position:absolute;z-index:1;left:1040px;top:-300px;width:180px;height:1600px;
    transform:rotate(16deg);transform-origin:top left;
    background:linear-gradient(180deg,rgba(140,159,178,.20),rgba(140,159,178,.07) 72%,rgba(140,159,178,0));}
  .soft-prism:after{content:"";position:absolute;left:100px;top:0;width:70px;height:1600px;background:rgba(255,255,255,.36);}
  .dot-field{position:absolute;z-index:1;opacity:.30;
    background-image:radial-gradient(circle,rgba(27,38,32,.42) 1.05px,transparent 1.15px);
    background-size:15px 15px;}
  .dot-a{left:120px;top:872px;width:760px;height:150px;opacity:.22;}
  .dot-b{left:1330px;top:60px;width:430px;height:120px;opacity:.26;}

  /* ---------- frame ---------- */
  .top-rule{position:absolute;left:96px;top:88px;width:1728px;height:1px;background:rgba(27,38,32,.34);z-index:6;}
  .bottom-rule{position:absolute;left:96px;top:976px;width:1728px;height:1px;background:rgba(27,38,32,.22);z-index:6;}
  .left-rule{position:absolute;left:62px;top:40px;width:1px;height:1000px;background:rgba(27,38,32,.24);z-index:6;}
  .rail-tick{position:absolute;left:56px;width:13px;height:1px;background:rgba(27,38,32,.42);z-index:7;}
  .rt1{top:236px;} .rt2{top:512px;} .rt3{top:900px;}
  .rail-label{position:absolute;left:46px;top:768px;width:420px;z-index:15;
    transform:rotate(-90deg);transform-origin:left top;
    font-size:13px;font-weight:600;letter-spacing:5.4px;color:#637067;white-space:nowrap;}

  .top-meta{position:absolute;left:98px;top:56px;z-index:15;font-size:15px;font-weight:600;
    letter-spacing:4px;color:#4f5b53;}
  .top-right-meta{position:absolute;right:98px;top:56px;z-index:15;font-size:13px;font-weight:600;
    letter-spacing:3.6px;color:#6b7568;text-align:right;}

  /* ---------- register (concentric) ---------- */
  .register{position:absolute;right:-96px;top:-118px;width:400px;height:400px;z-index:4;border-radius:50%;
    border:1px solid rgba(27,38,32,.30);}
  .register .r2{position:absolute;inset:14px;border-radius:50%;border:1px solid rgba(27,38,32,.16);}
  .register .r3{position:absolute;inset:34px;border-radius:50%;
    background:conic-gradient(from 210deg,rgba(79,94,67,.20),rgba(79,94,67,0) 24%,rgba(140,159,178,.30) 50%,rgba(140,159,178,.08) 78%,rgba(79,94,67,.20));}
  .register .r4{position:absolute;inset:48px;border-radius:50%;background:rgba(245,242,233,.88);
    border:1px solid rgba(27,38,32,.08);}
  .register .r5{position:absolute;inset:74px;border-radius:50%;background:rgba(140,159,178,.24);
    border:1px solid rgba(27,38,32,.09);}
  .register .dot{position:absolute;left:66px;top:250px;width:15px;height:15px;border-radius:50%;
    background:var(--gold);box-shadow:0 0 0 6px rgba(180,145,74,.13);}

  /* ---------- cover block ---------- */
  .eyebrow{position:absolute;left:152px;top:222px;z-index:12;display:flex;align-items:center;gap:18px;}
  .eyebrow .bar{width:56px;height:1px;background:var(--gold);}
  .eyebrow .txt{font-size:14px;font-weight:600;letter-spacing:7px;color:#8a6f36;}

  h1.title{position:absolute;left:146px;top:268px;margin:0;z-index:12;
    font-size:128px;line-height:1.12;font-weight:700;letter-spacing:10px;
    color:color-mix(in srgb,#1B2620 92%,black);}

  .title-rule{position:absolute;left:156px;top:452px;width:820px;height:1px;background:rgba(27,38,32,.30);z-index:12;}
  .title-rule:after{content:"";position:absolute;left:0;top:-1px;width:132px;height:3px;background:var(--olive);}

  .subtitle{position:absolute;left:156px;top:492px;z-index:12;font-size:30px;font-weight:500;
    letter-spacing:3px;color:#38463c;}

  .source-chip{position:absolute;left:156px;top:566px;z-index:12;display:flex;align-items:center;gap:14px;
    padding:14px 26px 14px 20px;border:1px solid rgba(79,94,67,.38);background:rgba(243,240,231,.78);}
  .source-chip .k{font-size:14px;font-weight:700;letter-spacing:2.6px;color:#4F5E43;}
  .source-chip .v{font-size:19px;letter-spacing:1.2px;color:#2b382f;}
  .source-chip .sq{width:7px;height:7px;background:var(--gold);}

  .note{position:absolute;left:156px;top:666px;z-index:12;font-size:16px;letter-spacing:1.6px;color:#6c766b;}

  /* ---------- coverage sequence (right) ---------- */
  .coverage{position:absolute;left:1180px;top:252px;width:640px;z-index:12;}
  .coverage .head{font-size:13px;font-weight:700;letter-spacing:5.2px;color:#6b7568;
    padding-bottom:14px;border-bottom:1px solid rgba(27,38,32,.30);}
  .cov-item{display:flex;align-items:baseline;gap:22px;padding:26px 4px 24px;border-bottom:1px solid rgba(27,38,32,.16);}
  .cov-item:last-child{border-bottom:none;}
  .cov-item .num{font-family:'Songti SC','Noto Serif CJK SC',Georgia,serif;font-size:22px;font-weight:700;
    letter-spacing:2px;color:#B4914A;min-width:44px;}
  .cov-item .label{font-size:27px;font-weight:600;letter-spacing:2.4px;color:#23302a;}
  .cov-item .tick{margin-left:auto;width:34px;height:1px;background:rgba(27,38,32,.28);align-self:center;}

  /* ---------- footer ---------- */
  .date-placeholder{position:absolute;left:98px;top:1004px;z-index:15;display:flex;align-items:center;gap:14px;}
  .date-placeholder .k{font-size:14px;font-weight:700;letter-spacing:3px;color:#5C665D;}
  .date-placeholder .v{font-size:15px;letter-spacing:1.4px;color:#8a8f84;
    border-bottom:1px dashed rgba(27,38,32,.34);padding-bottom:3px;}
  .page-no{position:absolute;right:98px;top:1000px;z-index:15;font-size:15px;font-weight:700;
    letter-spacing:4px;color:#657066;}
  .page-no .cur{color:#1B2620;}
</style>
</head>
<body>
<main class="slide">
  <div class="bg-field"></div>
  <div class="dot-field dot-a"></div>
  <div class="dot-field dot-b"></div>
  <div class="soft-prism"></div>
  <div class="gridline gl1"></div>
  <div class="gridline gl2"></div>
  <div class="gridline gl3"></div>

  <div class="top-rule"></div>
  <div class="bottom-rule"></div>
  <div class="left-rule"></div>
  <div class="rail-tick rt1"></div>
  <div class="rail-tick rt2"></div>
  <div class="rail-tick rt3"></div>
  <div class="rail-label">COVERAGE VERIFICATION · 覆盖核验</div>

  <div class="top-meta">企业资料治理项目组 · 内部核验汇报</div>
  <div class="top-right-meta">虚构测评材料</div>

  <div class="register">
    <div class="r2"></div>
    <div class="r3"></div>
    <div class="r4"></div>
    <div class="r5"></div>
    <div class="dot"></div>
  </div>

  <div class="eyebrow">
    <span class="bar"></span>
    <span class="txt">长资料覆盖核验</span>
  </div>

  <h1 class="title serif">长资料覆盖核验</h1>

  <div class="title-rule"></div>

  <div class="subtitle">企业资料治理项目组 · 内部核验汇报</div>

  <div class="source-chip">
    <span class="sq"></span>
    <span class="k">唯一事实来源</span>
    <span class="v">long-document.txt（虚构测评材料）</span>
  </div>

  <div class="note">全部数值均为资料原文可回读内容，不补充资料以外的日期、预算与业务成果。</div>

  <div class="coverage">
    <div class="head">覆盖顺序</div>
    <div class="cov-item">
      <span class="num">01</span>
      <span class="label">项目概况</span>
      <span class="tick"></span>
    </div>
    <div class="cov-item">
      <span class="num">02</span>
      <span class="label">整理流程</span>
      <span class="tick"></span>
    </div>
    <div class="cov-item">
      <span class="num">03</span>
      <span class="label">前中后部核验数据</span>
      <span class="tick"></span>
    </div>
    <div class="cov-item">
      <span class="num">04</span>
      <span class="label">结论与边界</span>
      <span class="tick"></span>
    </div>
  </div>

  <div class="date-placeholder">
    <span class="k">汇报日期</span>
    <span class="v">资料未提供（不补造日期）</span>
  </div>

  <div class="page-no"><span class="cur">1</span> / 6</div>
</main>
</body>
</html>
```
